const main = ( arg ) => {

    /*
     * This section parses the input string 'arg'.
     * It expects three space-separated numbers: N, X, and M.
     * These are assigned to respective constant variables.
     */
    const [ N , X , M ] = arg . split ( " " ) . map ( Number ) ;


    // 'tmp' will store the sequence of numbers generated by the process.
    // 'mods' acts as a lookup table to detect cycles; mods[value] stores the
    // index where 'value' was first encountered.
    // Both arrays are initialized with M elements, all set to 0.
    let tmp = [ ... new Array ( M ) ] . fill ( 0 ) ;
    let mods = [ ... new Array ( M ) ] . fill ( 0 ) ;

    // The first element of the sequence, tmp[0], is initialized with X.
    tmp [ 0 ] = X ;
    // The original code sets mods[0] to X. This might influence cycle detection
    // if '0' appears in the sequence later and X is not 0.
    mods [ 0 ] = X ;


    /*
     * Initialize variables for the sequence generation loop.
     * 'i' is the current index in the 'tmp' array.
     * 'loopStart' will store the starting index of a detected cycle.
     */
    let i = 1 , loopStart = 0 ;

    // This loop generates the sequence tmp[i] = tmp[i-1]^2 % M
    // and simultaneously detects if a number repeats, indicating a cycle.
    for ( ; i < M ; i++ ) {

        // Calculate the next element in the sequence.
        // It's the square of the previous element, modulo M.
        tmp [ i ] = tmp [ i - 1 ] ** 2 % M ;

        /*
         * Check if the current number (tmp[i]) has been seen before.
         * If mods[tmp[i]] is not 0, it means tmp[i] was previously encountered
         * at the index stored in mods[tmp[i]]. This signifies a loop.
         */
        if ( mods [ tmp [ i ] ] !== 0 ) {
            // A cycle has been detected.
            // 'loopStart' is set to the index where this repeating value was first seen.
            loopStart = mods [ tmp [ i ] ] ;
            // Break out of the loop as the cycle is identified.
            break ;
        }
        else {
            // If tmp[i] is a new number, record its first occurrence index.
            mods [ tmp [ i ] ] = i ;
        }
    }

    // 'loopEnd' captures the index where the cycle was completed (exclusive).
    const loopEnd = i ;
    // 'loopNum' is the length of the detected cycle.
    const loopNum = loopEnd - loopStart ;

    // Calculate how many full repetitions of the cycle fit into the remaining N values.
    // If 'loopNum' is 0 (no cycle detected or cycle of length 0), 'loopCount' remains 0.
    const loopCount = loopNum === 0 ? 0 : Math . floor ( N / ( loopNum ) ) ;


    // 'ans' will accumulate the total sum.
    let ans = 0 ;
    // 'sumOfLoop' will store the sum of elements within one full cycle.
    let sumOfLoop = 0 ;

    // Sum the elements that constitute one full cycle.
    for ( i = loopStart ; i < loopEnd ; i++ ) {
        sumOfLoop += tmp [ i ] ;
    }

    // Add the sum of all full cycles to the total answer.
    ans += sumOfLoop * loopCount ;


    // Add the sum of elements that occur before the cycle begins.
    // These are elements from index 0 up to (but not including) loopStart.
    for ( i = 0 ; i < loopStart ; i++ ) {
        ans += tmp [ i ] ;
    }


    // Calculate the number of remaining elements after accounting for
    // the pre-loop part and the full cycle repetitions.
    // These 'rest' elements form a partial segment of the cycle.
    const rest = loopNum === 0 ? 0 : N - loopStart - ( loopNum ) * loopCount ;

    // Add the sum of these 'rest' elements to the total answer.
    // These elements are taken from the beginning of the detected cycle.
    for ( i = loopStart ; i < loopStart + rest ; i++ ) {
        ans += tmp [ i ] ;
    }

    // Output the final calculated total sum.
    console . log ( ans ) ;
} ;


/*
 * Example calls to the 'main' function.
 * The last uncommented call is the active one in the original code.
 */
// main ( "6 2 1001" ) ;
// main ( "100 2 1002" ) ;
main ( "1000 2 16" ) ;
